-- Quokka360 synthetic scenario as of 17 November 2026. TEST ONLY.
-- 36 stays, 72 registered guests, simulated channels/payments/documents/compliance.
-- No OTA/Octorate IDs, Stripe IDs, external transmissions or invitations.
-- Markers use dedicated origin quokka-scenario-test; no existing records are removed.
-- Private proof files must be uploaded and verified BEFORE this transaction.
-- Restart existing TEST backend after commit to encrypt synthetic data through native EF.
BEGIN;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM casazen_test."Bookings" WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8')
 THEN RAISE EXCEPTION 'Quokka bookings already exist; review instead of duplicate seed'; END IF;
 IF (SELECT count(*) FROM casazen_test."Properties" WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "IsTestData" AND NOT "IsDeleted")<>3
 THEN RAISE EXCEPTION 'Expected exactly three Quokka test properties'; END IF;
 IF EXISTS (SELECT 1 FROM casazen_test."OrgFiscalIssuerProfiles" WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "PropertyOwnerId" IS NULL)
 THEN RAISE EXCEPTION 'Organization issuer already exists; review before replacing'; END IF;
END $$;
-- Final scenario consistency: fixed-price invoice lines, historical owner coverage, and TEST-only fiscal approval.
UPDATE casazen_test."FiscalDocumentLines" l SET "Quantity"=1,"UnitPrice"=l."TotalPrice"
FROM casazen_test."FiscalDocuments" d,casazen_test."TestDataMarkers" m
WHERE l."DocumentId"=d."Id" AND m."EntityId"=d."Id" AND m."EntityType"='FiscalDocument'
AND m."Origin"='quokka-scenario-test' AND l."OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND d."OrgId"=l."OrgId" AND m."OrgId"=l."OrgId";
UPDATE casazen_test."InternalActivities" a SET "StaffUserId"='auth0|6afb6c7bb2c0f85f4e97f136'
FROM casazen_test."Bookings" b,casazen_test."TestDataMarkers" m
WHERE a."BookingId"=b."Id" AND a."OrgId"=b."OrgId" AND b."CheckInDate"<'2026-11-23'
AND m."EntityId"=b."Id" AND m."EntityType"='Booking' AND m."Origin"='quokka-scenario-test' AND a."OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
UPDATE casazen_test."PropertyOwnerships" SET "OwnershipStart"='2026-10-01T00:00:00Z'
WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "PropertyOwnerId"='fa985716-6d5a-4c5a-b554-140a6ea00e9e';
UPDATE casazen_test."OwnerMandates" SET "ValidFrom"='2026-10-01'
WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "PropertyOwnerId"='fa985716-6d5a-4c5a-b554-140a6ea00e9e';
UPDATE casazen_test."OwnerFiscalProfiles" SET "ValidFrom"='2026-10-01',"MandateFrom"='2026-10-01'
WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "PropertyOwnerId"='fa985716-6d5a-4c5a-b554-140a6ea00e9e';
UPDATE casazen_test."OwnerAccountingPolicies"
SET "ValidFrom"='2026-10-01',"ApprovedAt"=now(),"ApprovedByUserId"='auth0|6afb6c7bb2c0f85f4e97f136',
"ApprovedByName"='SIMULAZIONE TEST - nessuna validazione professionale reale'
WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "RuleCode"='QUOKKA-SYNTHETIC-TEST' AND "ApprovedAt" IS NULL;
COMMIT;